# Construct the output grid
# Pattern from top-middle region (cols 4-6) should be copied to all regions

pattern = [
    [9, 6, 6],
    [6, 6, 9],
    [3, 6, 6],
    [6, 7, 6],
]

# Build output grid
# Each region is 4x3, separators are 1s
output = [[0]*11 for _ in range(9)]

for r in range(4):
    for c in range(3):
        output[r][c] = pattern[r][c]  # top-left region

# Horizontal separator row 4
for c in range(11):
    output[4][c] = 1

for r in range(4):
    for c in range(3):
        output[r][c+8] = pattern[r][c]  # top-right region

# Bottom regions
for r in range(4):
    for c in range(3):
        output[r+5][c] = pattern[r][c]  # bottom-left region

for r in range(4):
    for c in range(3):
        output[r+5][c+8] = pattern[r][c]  # bottom-right region

# Print the output
for row in output:
    print(' '.join(map(str, row)))

# Verify special values
from collections import Counter
flat = [v for row in output for v in row]
counts = Counter(flat)
print(f"\nBackground count: {counts.most_common(1)}")

